WITH matched_keys AS (SELECT id, product_id FROM order_items EXCEPT SELECT id, product_id FROM order_items WHERE quantity != 4), verified AS (SELECT s.* FROM order_items s JOIN matched_keys k ON s.id = k.id AND s.product_id = k.product_id) SELECT product_id, STDDEV_SAMP(unit_price) AS unit_price_stddev, PERCENTILE_APPROX(quantity, 0.5) AS quantity_p50, MIN(unit_price) AS min_unit_price, PERCENTILE_APPROX(unit_price, ARRAY(0.25, 0.5, 0.75)) AS unit_price_quartiles, COUNT(*) AS event_count FROM verified GROUP BY product_id ORDER BY event_count NULLS FIRST;
